def rec_tri(P,x,y,s,depth):
    if depth==0:return P.p(f'M{x} {y}l{s} 0l{-s*.5} {-s*.866}Z',P.a if int(x)%2 else P.b,P.i,.65)
    return rec_tri(P,x,y,s/2,depth-1)+rec_tri(P,x+s/2,y,s/2,depth-1)+rec_tri(P,x+s/4,y-s*.433,s/2,depth-1)
def hilbert(n):
    def xy(d):
        x=y=0;t=d;s=1
        while s<n:
            rx=(t//2)&1;ry=(t^rx)&1
            if not ry:
                if rx:x=s-1-x;y=s-1-y
                x,y=y,x
            x+=s*rx;y+=s*ry;t//=4;s*=2
        return x,y
    return [xy(d) for d in range(n*n)]
